conditions.value_template:
{% set age = as_timestamp(now()) - as_timestamp(states('sensor.garage_deye_energy_manager_solar_plan_generated_at'), 0) %}
{% set rec = states('sensor.garage_deye_energy_manager_solar_plan_recommended_ev_amps') | int(-1) %}
{% set plan_ok = states('sensor.garage_deye_energy_manager_solar_plan_status') == 'advisory' and is_number(states('sensor.garage_deye_energy_manager_solar_plan_recommended_ev_amps')) and is_number(states('sensor.garage_deye_energy_manager_solar_plan_expected_battery_dc_power')) and -5 <= age <= 90 %}
{% set status = states('sensor.evcharger_status_connector') %}
{% set connected_now = status in ['Preparing', 'Charging', 'SuspendedEV', 'SuspendedEVSE', 'Finishing'] %}
{% set gates = is_state('switch.garage_deye_energy_manager_ev_manual_charging_override', 'off') and 7 <= now().hour < 21 and is_state('select.garage_deye_energy_manager_daytime_ev_writer', 'external_automation') and is_state('switch.garage_deye_energy_manager_enabled', 'on') and is_state('switch.garage_deye_energy_manager_ev_control_enabled', 'on') and is_state('switch.garage_deye_energy_manager_ev_solar_charging_enabled', 'on') %}
{% set soc_age = as_timestamp(now()) - as_timestamp(states.sensor.deye_battery_soc.last_reported, 999999) if states.sensor.deye_battery_soc.last_reported is defined else 999999 %}
{% set soc_fresh = is_number(states('sensor.deye_battery_soc')) and -5 <= soc_age <= 120 %}
{% set target_met = is_number(states('sensor.garage_deye_energy_manager_ev_active_target_soc')) and is_number(states('sensor.garage_deye_energy_manager_effective_taycan_soc')) and states('sensor.garage_deye_energy_manager_effective_taycan_soc') | float(0) >= states('sensor.garage_deye_energy_manager_ev_active_target_soc') | float(100) - states('input_number.ev_solar_target_tolerance_pct') | float(0.5) %}
{% set ev_v_age = as_timestamp(now()) - as_timestamp(states.sensor.evcharger_voltage.last_reported, 999999) if states.sensor.evcharger_voltage.last_reported is defined else 999999 %}
{% set grid_v_age = as_timestamp(now()) - as_timestamp(states.sensor.deye_grid_voltage.last_reported, 999999) if states.sensor.deye_grid_voltage.last_reported is defined else 999999 %}
{% set v = states('sensor.evcharger_voltage') | float(0) if is_number(states('sensor.evcharger_voltage')) and -5 <= ev_v_age <= 120 else (states('sensor.deye_grid_voltage') | float(0) if is_number(states('sensor.deye_grid_voltage')) and -5 <= grid_v_age <= 120 else 0) %}
{% set p_age = as_timestamp(now()) - as_timestamp(states.sensor.evcharger_power_active_import.last_reported, 999999) if states.sensor.evcharger_power_active_import.last_reported is defined else 999999 %}
{% set i_age = as_timestamp(now()) - as_timestamp(states.sensor.evcharger_current_import.last_reported, 999999) if states.sensor.evcharger_current_import.last_reported is defined else 999999 %}
{% set p_ok = is_state('input_boolean.ev_solar_ev_telemetry_verified', 'on') and is_number(states('sensor.evcharger_power_active_import')) and -5 <= p_age <= 120 %}
{% set i_ok = is_state('input_boolean.ev_solar_ev_telemetry_verified', 'on') and is_number(states('sensor.evcharger_current_import')) and -5 <= i_age <= 120 %}
{% set ev_w = states('sensor.evcharger_power_active_import') | float(0) * 1000 if p_ok else (states('sensor.evcharger_current_import') | float(0) * v if i_ok and v > 0 else 0) %}
{% set essential = states('sensor.deye_essential_power') | float(-1) %}
{% set base = states('sensor.garage_deye_energy_manager_base_load_estimate') | float(0) %}
{% set non_ev = [base, essential - ev_w, 0] | max if p_ok or i_ok else [base, essential] | max %}
{% set room = ((states('input_number.ev_solar_site_ceiling_w') | float(13500) - non_ev) / v) | int(0) if v > 0 and essential >= 0 else 0 %}
{% set site_ok = v > 0 and essential >= 0 and room >= 6 %}
{% set ev_telemetry_ok = p_ok and i_ok %}
{% set plan_target_ok = states('sensor.garage_deye_energy_manager_solar_plan_target_reachable') == 'yes' %}
{{ plan_ok and ev_telemetry_ok and site_ok and is_number(states('sensor.deye_battery_power')) and is_number(states('sensor.deye_grid_ct_power')) and -5 <= (as_timestamp(now()) - as_timestamp(states.sensor.deye_battery_power.last_reported, 999999)) <= 120 and -5 <= (as_timestamp(now()) - as_timestamp(states.sensor.deye_grid_ct_power.last_reported, 999999)) <= 120 }}
